package com.bank.audit;

import java.util.Arrays;
import java.util.logging.*;

public class BoundaryDemo {
    private static final Logger log = Logger.getLogger(BoundaryDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Transaction amounts sorted ascending, with 50000 repeated
        int[] amounts = {1000, 20000, 50000, 50000, 50000, 70000, 90000};

        BoundarySearchService service = new BoundarySearchService();

        log.info("Finding range for amount 50000 (appears multiple times)");
        int[] range1 = service.findRange(amounts, 50000);
        log.info("Range -> " + Arrays.toString(range1)
            + " count=" + (range1[0] == -1 ? 0 : range1[1] - range1[0] + 1));

        log.info("Finding range for missing amount 30000");
        int[] range2 = service.findRange(amounts, 30000);
        log.info("Range -> " + Arrays.toString(range2));
    }
}

// ─── Would be in service/BoundarySearchService.java ───
class BoundarySearchService {
    int[] findRange(int[] arr, int target) {
        int first = findFirst(arr, target);
        if (first == -1) return new int[]{-1, -1};  // absent: skip second search
        int last = findLast(arr, target);
        return new int[]{first, last};
    }

    // Leftmost occurrence: on a match, keep going left.
    int findFirst(int[] arr, int target) {
        int low = 0, high = arr.length - 1, result = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == target) {
                result = mid;
                high = mid - 1;        // bias left
            } else if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result;
    }

    // Rightmost occurrence: on a match, keep going right.
    int findLast(int[] arr, int target) {
        int low = 0, high = arr.length - 1, result = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == target) {
                result = mid;
                low = mid + 1;         // bias right
            } else if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result;
    }
}

